async function main() {
  console.log("Seeding database...");

  // Admin user
  const adminEmail = process.env.ADMIN_EMAIL || "admin@example.com";
  const adminPassword = process.env.ADMIN_PASSWORD || "admin123";
  const passwordHash = await bcrypt.hash(adminPassword, 12);

  await prisma.adminUser.upsert({
    where: { email: adminEmail },
    update: { password_hash: passwordHash },
    create: {
      email: adminEmail,
      password_hash: passwordHash,
      role: "super_admin",
    },
  });
  console.log(`Admin user: ${adminEmail}`);

  // Seed fonts
  for (const fontData of fonts) {
    const { aliases, ...data } = fontData;
    const slug = slugify(fontData.font_name);
    const normalized_name = normalize(fontData.font_name);

    const font = await prisma.font.upsert({
      where: { slug },
      update: { ...data, normalized_name, last_verified_at: new Date() },
      create: { ...data, slug, normalized_name, last_verified_at: new Date() },
    });

    if (aliases && aliases.length > 0) {
      for (const alias of aliases) {
        await prisma.fontAlias.upsert({
          where: { id: `alias-${font.id}-${normalize(alias)}` },
          update: {},
          create: {
            id: `alias-${font.id}-${normalize(alias)}`,
            font_id: font.id,
            alias_name: alias,
            normalized_alias_name: normalize(alias),
          },
        });
      }
    }

    console.log(`  ✓ ${fontData.font_name}`);
  }

  console.log(`\nDone. ${fonts.length} fonts seeded.`);
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });
